#include "ComponentGuard.h"
#include <chrono>
int main(){namespace fs=std::filesystem;auto root=fs::temp_directory_path()/("lg-components-"+std::to_string(std::chrono::steady_clock::now().time_since_epoch().count()));if(!fs::create_directory(root))return 1;struct Cleanup{fs::path p;~Cleanup(){std::error_code e;fs::remove_all(p,e);}} cleanup{root};for(auto& n:components::names)std::ofstream(root/n)<<n;auto p=root/"manifest";auto a=recovery::stream(root/components::names[0]),b=recovery::stream(root/components::names[1]);auto write=[&](std::string s){std::ofstream(p)<<s;};auto good=a+" LocalGuard.exe\n"+b+" RecoveryCopy.exe\n";components::Manifest m;write(good);if(!components::read(p,m)||!components::verify(root,m))return 2;write(good+good);if(components::read(p,m))return 3;write(a+" ../LocalGuard.exe\n");if(components::read(p,m))return 4;write(good);std::ofstream(root/components::names[1],std::ios::app)<<"changed";if(components::verify(root,m))return 5;fs::remove(root/components::names[1]);if(components::verify(root,m))return 6;write(std::string(513,'x'));if(components::read(p,m))return 7;std::cout<<"component integrity checks passed\n";}
